package com.estateflow.service;
import com.estateflow.config.UserPreferences;import com.estateflow.dto.*;import com.estateflow.exception.AuthorizationException;import com.estateflow.model.*;import com.estateflow.support.TestAuth;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.*;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class NotificationServiceTest{
 private static final Clock CLOCK=Clock.fixed(Instant.parse("2026-10-10T00:00:00Z"),ZoneOffset.UTC);private final RentReminderService rent=mock(RentReminderService.class);private final LeaseRenewalService leases=mock(LeaseRenewalService.class);private final WorkOrderService workOrders=mock(WorkOrderService.class);private final UserPreferences prefs=UserPreferences.defaults();
 private NotificationService service(){return new NotificationService(rent,leases,workOrders,prefs,CLOCK,30,TestAuth.admin());}
 @Test void aggregatesCurrentSourcesAndMarksRowsGenerated() throws Exception{when(rent.reminders()).thenReturn(List.of(new RentReminderRow(3,7,"Flat A","Tenant A",null,LocalDate.of(2026,10,1),LocalDate.of(2026,10,5),new BigDecimal("500.00"),-5)));when(leases.endingWithinWarningWindow(30)).thenReturn(List.of(new ExpiringLeaseRow(8,"Flat B","Tenant B",LocalDate.of(2026,10,17),7,new BigDecimal("1200"),false)));when(workOrders.isAvailable()).thenReturn(true);when(workOrders.search(null,null,null,null,null,null,true)).thenReturn(List.of(new WorkOrderRow(10L,"Flat C","Vendor",2L,"Broken gate",com.estateflow.model.enums.MaintenancePriority.HIGH,LocalDate.of(2026,10,8),WorkOrderStatus.IN_PROGRESS,null,new BigDecimal("80"),null)));
  var rows=service().generate();assertEquals(3,rows.size());assertTrue(rows.stream().allMatch(n->"Generated".equals(n.deliveryState())));assertEquals(2,rows.stream().filter(n->n.severity()==NotificationSeverity.HIGH).count());var again=service().generate();assertEquals(rows.stream().map(GeneratedNotification::key).toList(),again.stream().map(GeneratedNotification::key).toList());verify(rent,times(2)).reminders();}
 @Test void preferencesDisableSourcesWithoutPersistingDelivery() throws Exception{prefs.updateReminderPreferences(false,false,false);var rows=service().generate();assertTrue(rows.isEmpty());verifyNoInteractions(rent,leases,workOrders);}
 @Test void missingWorkOrderMigrationLeavesRentAndLeaseRemindersAvailable() throws Exception{prefs.updateReminderPreferences(true,true,true);when(rent.reminders()).thenReturn(List.of());when(leases.endingWithinWarningWindow(30)).thenReturn(List.of());when(workOrders.isAvailable()).thenReturn(false);assertTrue(service().generate().isEmpty());verify(workOrders,never()).search(any(),any(),any(),any(),any(),any(),anyBoolean());}
 @Test void duplicateSourceRowsCollapseToOneGeneratedReminder() throws Exception{RentReminderRow duplicate=new RentReminderRow(3,7,"Flat A","Tenant A",null,LocalDate.of(2026,10,1),LocalDate.of(2026,10,5),new BigDecimal("500.00"),-5);when(rent.reminders()).thenReturn(List.of(duplicate,duplicate));when(leases.endingWithinWarningWindow(30)).thenReturn(List.of());assertEquals(1,service().generate().size());}
 @Test void unauthenticatedUserIsRejectedBeforeReadingSources() throws Exception{NotificationService secured=new NotificationService(rent,leases,workOrders,prefs,CLOCK,30,TestAuth.signedOut());assertThrows(AuthorizationException.class,secured::generate);verifyNoInteractions(rent,leases,workOrders);}
}
